const lead = $input.first().json;
const triggerData = $('RabbitMQ Trigger').first().json.data || {};

const prompt = `
You are an expert B2B Lead Qualification AI. Evaluate the following lead:

Name: ${lead.firstName} ${lead.lastName || ''}
Email: ${lead.email}
Company: ${lead.companyName || 'Not specified'}
Website: ${lead.companyWebsite || 'Not specified'}
Job Title: ${lead.jobTitle || 'Not specified'}
Industry: ${lead.industry || 'Not specified'}
Company Size: ${lead.companySize || 'Not specified'}
Notes: ${lead.notes || 'None'}

Decision Rule:
- Confidence score must be between 0.00 and 1.00.
- If confidence >= 0.80, status can be QUALIFIED or DISQUALIFIED.
- If confidence < 0.80 or data is highly ambiguous, status should be NEEDS_REVIEW with reviewRequired=true.

Respond ONLY with a valid JSON object in this exact schema:
{
  "qualification": "QUALIFIED" | "DISQUALIFIED" | "NEEDS_REVIEW",
  "confidence": 0.85,
  "intent": "Brief intent summary",
  "reason": "Detailed explanation",
  "nextAction": "Recommended next sales step",
  "reviewRequired": false
}
`;

return [{
  json: {
    leadId: lead.id,
    workflowRunId: triggerData.workflowRunId || null,
    leadSnapshot: lead,
    prompt
  }
}];

const response = $input.first().json;
const prep = $('Prepare AI Input').first().json;

let aiOutput;
try {
  const content = response.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
  aiOutput = JSON.parse(content);
} catch (err) {
  aiOutput = {
    qualification: 'NEEDS_REVIEW',
    confidence: 0.5,
    intent: 'Failed to parse AI output',
    reason: 'Raw response format invalid',
    nextAction: 'Manual review required',
    reviewRequired: true
  };
}

const confidence = typeof aiOutput.confidence === 'number' ? aiOutput.confidence : 0.5;
const reviewRequired = confidence < 0.80 || aiOutput.qualification === 'NEEDS_REVIEW' || aiOutput.reviewRequired === true;

return [{
  json: {
    leadId: prep.leadId,
    workflowRunId: prep.workflowRunId,
    status: aiOutput.qualification || 'NEEDS_REVIEW',
    intent: aiOutput.intent || null,
    confidence: Math.min(1, Math.max(0, confidence)),
    reason: aiOutput.reason || null,
    nextAction: aiOutput.nextAction || null,
    reviewRequired,
    modelProvider: 'google',
    modelName: $env.GEMINI_MODEL || 'gemini-1.5-pro',
    modelVersion: 'v1beta',
    inputSnapshot: prep.leadSnapshot,
    outputSnapshot: aiOutput
  }
}];
